def resolved_command(context):
    frozen = context['frozen_root_command']
    need(isinstance(frozen, list) and len(frozen) == 9 and
         all(isinstance(value, str) for value in frozen), 'closed frozen root argv shape')
    file_bytes = (json.dumps(frozen, indent=2, sort_keys=True) + '\n').encode()
    need(sha(file_bytes) == FROZEN_COMMAND_FILE_SHA256 == context['frozen_root_command_file_sha256'],
         'separate exact unresolved frozen command file-byte identity')
    need(frozen[-2:] == ['{SOURCE}/swdb-project', '{OUTPUT}'], 'exact source/output placeholder positions')
    resolved = [value.replace('{SOURCE}', str(SOURCE)).replace('{OUTPUT}', str(RAW)) for value in frozen]
    need(digest(resolved) == RESOLVED_COMMAND_SHA256 == context['resolved_root_command_sha256'],
         'separate canonical resolved actual argv identity')
    return resolved


